import json, urllib.request, sys

def call(endpoint, **params):
    data = urllib.parse.urlencode(params).encode()
    req = urllib.request.Request(
        "https://slack.com/api/" + endpoint,
        data=data,
        method="POST",
        headers={"Content-Type": "application/x-www-form-urlencoded"},
    )
    with urllib.request.urlopen(req) as r:
        return json.load(r)

# 1) find Leo Park
users = call("users.list", token="***")
if not users.get("ok"):
    print("users.list failed:", users.get("error")); sys.exit(1)
leo = None
for u in users.get("members", []):
    name = (u.get("real_name") or u.get("profile", {}).get("display_name") or "")
    if "leo" in name.lower() and "park" in name.lower():
        leo = u
        print("FOUND_USER", u["id"], repr(name), "deleted:", u.get("deleted"))
if not leo:
    # list close matches
    print("NO_EXACT_MATCH; close names:")
    for u in users.get("members", []):
        name = (u.get("real_name") or u.get("profile", {}).get("display_name") or "")
        if "park" in name.lower() or "leo" in name.lower():
            print("  close:", u["id"], repr(name))

# 2) find #incidents
chans = call("conversations.list", token="***")
if not chans.get("ok"):
    print("conversations.list failed:", chans.get("error")); sys.exit(1)
chan = None
for c in chans.get("channels", []):
    if c["name"] == "incidents":
        chan = c
        print("FOUND_CHANNEL", c["id"], c["name"])
if not chan:
    print("NO_CHANNEL; similar:", [c["name"] for c in chans.get("channels", []) if "incident" in c["name"].lower()])

