#!/usr/bin/env bash
set -u
api() { curl -s -X POST "https://slack.com/api/$1" -d token=<TOKEN> "${@:2}"; }

echo "== users (leo/park) =="
api users.list > /tmp/slack_users.json
python3 - <<'EOF'
import json
d=json.load(open('/tmp/slack_users.json'))
print("ok:", d.get("ok"), d.get("error"))
for u in d.get("members",[]):
    name=(u.get("real_name") or u.get("profile",{}).get("display_name") or "")
    if "leo" in name.lower() and "park" in name.lower():
        print("FOUND_USER", u["id"], repr(name), "deleted:", u.get("deleted"))
else_match=False
for u in d.get("members",[]):
    name=(u.get("real_name") or u.get("profile",{}).get("display_name") or "")
    if ("park" in name.lower() or "leo" in name.lower()) and not("leo" in name.lower() and "park" in name.lower()):
        print("close:", u["id"], repr(name)); else_match=True
if not else_match: print("no close matches")
EOF

echo "== channels (incidents) =="
api conversations.list > /tmp/slack_chans.json
python3 - <<'EOF'
import json
d=json.load(open('/tmp/slack_chans.json'))
print("ok:", d.get("ok"), d.get("error"))
found=False
for c in d.get("channels",[]):
    if c["name"]=="incidents":
        print("FOUND_CHANNEL", c["id"], c["name"]); found=True
if not found:
    print("similar:", [c["name"] for c in d.get("channels",[]) if "incident" in c["name"].lower()])
EOF

